<template>
  <div>
    <div style="display: flex; align-items: center; gap: 16px; margin-bottom: 16px;">
    <span v-if="loadedAt" style="color: #999; font-size: 13px;">
      上一次更新规则：{{ formatTime(loadedAt) }} | 共 {{ rules.length }} 条规则
      <a-button type="link" size="small" :loading="loading" @click="handleReload" style="padding: 0 4px;">刷新</a-button>
    </span>
      <span v-else style="color: #999; font-size: 13px;">尚未加载筛选配置</span>
    </div>

    <a-table
      :dataSource="rules"
      :columns="columns"
      rowKey="fieldName"
      :pagination="{ pageSize: 50 }"
      :loading="loading"
      size="small"
      bordered
    >

      <template #bodyCell="{ column, record }">
        <template v-if="column.key === 'index'">
          {{ record.fieldName?.replace('Cell', '') }}
        </template>
        <template v-if="column.key === 'comment'">
          <a-input
            v-model:value="record.comment"
            size="small"
            style="width: 60%;"
            placeholder="添加注释"
          />
        </template>
        <template v-if="column.key === 'minValue'">
          <a-input-number
            v-model:value="record.minValue"
            :min="-9999999"
            :precision="3"
            :step="0.001"
            size="small"
            style="width: 110px;"
            :placeholder="'不限'"
          />
        </template>
        <template v-if="column.key === 'maxValue'">
          <a-input-number
            v-model:value="record.maxValue"
            :min="-9999998"
            :precision="3"
            :step="0.001"
            size="small"
            style="width: 110px;"
            :placeholder="'不限'"
          />
        </template>
        <template v-if="column.key === 'action'">
          <a-button
            type="link"
            size="small"
            :loading="record._saving"
            @click="handleSave(record)"
          >
            保存
          </a-button>
        </template>
      </template>
    </a-table>
  </div>
</template>

<script lang="ts" setup>
import { ref, onMounted } from "vue";
import { message } from "ant-design-vue";
import { getFilters, updateConfig } from "@/api/filterConfig";

const loading = ref(false);
const rules = ref<any[]>([]);
const loadedAt = ref("");

const columns = [
  { title: "序号", key: "index", width: 60 },
  { title: "字段名", dataIndex: "fieldName", key: "fieldName", width: 50 },
  { title: "注释", dataIndex: "comment", key: "comment", width: 300 },
  { title: "最小值", key: "minValue", width: 120 },
  { title: "最大值", key: "maxValue", width: 120 },
  { title: "操作", key: "action", width: 70 },
];

onMounted(handleLoadConfig);

async function handleLoadConfig() {
  loading.value = true;
  try {
    const res = await getFilters();
    const data = res.data;
    if (data.loaded) {
      rules.value = data.rules ?? [];
      loadedAt.value = data.loadedAt;
    } else {
      rules.value = [];
      loadedAt.value = "";
    }
  } catch {
    message.error("获取配置失败");
  } finally {
    loading.value = false;
  }
}

async function handleSave(record: any) {
  record._saving = true;
  try {
    const res = await updateConfig({
      id: record.id,
      minValue: record.minValue ?? null,
      maxValue: record.maxValue ?? null,
      comment: record.comment ?? null,
    });
    message.success(`${record.fieldName} 已更新`);
    // 更新当前行的 displayedData 时间
    loadedAt.value = res.data.loadedAt;
  } catch (e: any) {
    message.error(e?.response?.data?.message ?? "保存失败");
  } finally {
    record._saving = false;
  }
}

async function handleReload() {
  loading.value = true;
  try {
    const { refreshFilters } = await import("@/api/filterConfig");
    const res = await refreshFilters();
    message.success(res.data.message);
    await handleLoadConfig();
  } catch (e: any) {
    message.error(e?.response?.data?.message ?? "刷新失败");
  } finally {
    loading.value = false;
  }
}

function formatTime(iso: string) {
  const d = new Date(iso);
  const pad = (n: number) => n.toString().padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}
</script>